// Build an alert that names the workflow, the node, and the error.
// A bare "workflow failed" trains you to ignore alerts.
const e = $json.execution ?? {};
const w = $json.workflow ?? {};

const lines = [
  `🔴 *${w.name ?? 'Unknown workflow'}* failed`,
  `Node: ${e.lastNodeExecuted ?? 'unknown'}`,
  `Error: ${e.error?.message ?? 'no message'}`,
  e.url ? `Execution: ${e.url}` : `Execution ID: ${e.id ?? 'unknown'}`,
  `Mode: ${e.mode ?? 'unknown'}${e.retryOf ? ` (retry of ${e.retryOf})` : ''}`,
];

return [{ json: { alert: lines.join('\n'), workflowName: w.name, nodeName: e.lastNodeExecuted } }];
